-- Mana Bazar REAL DB Schema
create table profiles (id uuid primary key, phone text unique, role text check (role in ('customer','shop_owner','delivery_boy','admin')), name text, area text, created_at timestamptz default now());
create table shops (id uuid primary key default gen_random_uuid(), owner_id uuid references profiles(id), shop_name text, category text, area text, address text, pincode text, phone text, upi_id text, status text default 'pending', delivery_radius_km int default 5, delivery_charge int default 30, has_own_boys boolean default false, created_at timestamptz default now());
create table products (id uuid primary key default gen_random_uuid(), shop_id uuid references shops(id), name text, category text, description text, price numeric, mrp numeric, image_url text, stock int, unit text, is_available boolean default true, status text default 'pending');
create table delivery_boys (id uuid primary key default gen_random_uuid(), user_id uuid references profiles(id), boy_type text check (boy_type in ('app_boy','shop_boy','customer_boy')), shop_id uuid references shops(id), vehicle text, vehicle_number text, upi_id text, status text default 'pending', is_online boolean default false);
create table orders (id uuid primary key default gen_random_uuid(), customer_id uuid, shop_id uuid, delivery_mode text check (delivery_mode in ('app_boy','shop_boy','self_pickup','customer_boy')), delivery_boy_id uuid references delivery_boys(id), total numeric, delivery_fee numeric, platform_fee numeric, shop_amount numeric, payment_mode text, payment_status text default 'pending', order_status text default 'placed', pickup_otp text, customer_boy_name text, customer_boy_phone text, created_at timestamptz default now());
create table subscriptions (id uuid primary key default gen_random_uuid(), shop_id uuid references shops(id), plan text check (plan in ('FREE','PRO','PREMIUM')), amount numeric, starts_at timestamptz, ends_at timestamptz, status text default 'active');
